<script setup lang="ts">
import { onMounted, ref } from 'vue'
import OrganizationTree from '../components/OrganizationTree.vue'
import { getOrganizationAudit, getOrganizationTree, getOrganizationUnit, previewOrganizationUser, updateOrganizationPerson, type OrgUnit } from '../api/organization'

const units=ref<OrgUnit[]>([]), selected=ref(''), detail=ref<any>(null), preview=ref<any>(null), audit=ref<any[]>([])
const editing=ref<any>(null)
async function selectUnit(code:string){selected.value=code;detail.value=await getOrganizationUnit(code);preview.value=null}
async function previewPerson(person:any){preview.value=await previewOrganizationUser(person.user_id)}
function editPerson(person:any){editing.value={...person,primary_org_code:selected.value,secondary_org_codes:'',manager_org_codes:'',sensitivities:''}}
async function savePerson(){const p=editing.value;await updateOrganizationPerson(p.person_code,{active:Boolean(p.active),job_title:p.job_title,primary_org_code:p.primary_org_code,secondary_org_codes:p.secondary_org_codes.split(',').map((v:string)=>v.trim()).filter(Boolean),manager_org_codes:p.manager_org_codes.split(',').map((v:string)=>v.trim()).filter(Boolean),sensitivities:p.sensitivities.split(',').map((v:string)=>v.trim()).filter(Boolean)});editing.value=null;await selectUnit(selected.value)}
onMounted(async()=>{units.value=await getOrganizationTree();audit.value=await getOrganizationAudit();if(units.value.length)await selectUnit(units.value[0].code)})
function roleText(role:string){return role==='read'?'可查看':role==='manage'?'可管理':'可管理全部'}
</script>
<template><div class="org-admin"><header><h1>组织权限</h1><p>管理组织、员工、负责人和知识库访问范围</p></header><div class="org-layout"><aside><OrganizationTree :units="units" :selected="selected" @select="selectUnit"/></aside><main v-if="detail"><h2>{{detail.unit.name}}</h2><section><h3>人员</h3><div v-for="person in detail.people" :key="person.person_code" class="person"><div><strong>{{person.display_name}}</strong><span>{{person.person_code}} · {{person.job_title}}</span></div><div><button :data-test="`preview-${person.person_code}`" @click="previewPerson(person)">查看权限</button><button @click="editPerson(person)">编辑</button></div></div></section><section><h3>知识库</h3><p v-if="!detail.knowledge_bases.length">暂无知识库</p><div v-for="kb in detail.knowledge_bases" :key="kb.kb_id">{{kb.name}}</div></section></main><aside class="preview"><template v-if="editing"><h2>编辑人员</h2><label>职位<input v-model="editing.job_title"/></label><label>主部门<select v-model="editing.primary_org_code"><option v-for="unit in units" :key="unit.code" :value="unit.code">{{unit.name}}</option></select></label><label>兼职部门编号<input v-model="editing.secondary_org_codes" placeholder="多个编号用逗号分隔"/></label><label>负责人范围<input v-model="editing.manager_org_codes" placeholder="多个编号用逗号分隔"/></label><label>敏感资格<input v-model="editing.sensitivities" placeholder="finance,hr,customer"/></label><label><input v-model="editing.active" type="checkbox"/>账号启用</label><button @click="savePerson">保存</button><button @click="editing=null">取消</button></template><template v-else><h2>权限预览</h2><template v-if="preview"><div v-for="kb in preview.knowledge_bases" :key="kb.kb_id" class="preview-kb"><span>{{kb.name}}</span><strong>{{roleText(kb.effective_role)}}</strong></div></template><p v-else>选择员工查看其实际可见范围</p><h3>最近操作</h3><p v-if="!audit.length">暂无记录</p><div v-for="event in audit.slice(0,8)" :key="event.id">{{event.action}}</div></template></aside></div></div></template>
<style scoped>.org-admin{padding:24px;height:100%;overflow:auto}.org-admin header p{color:var(--color-secondary)}.org-layout{display:grid;grid-template-columns:240px minmax(420px,1fr) 320px;gap:16px}.org-layout>aside,.org-layout>main{background:var(--color-surface);border:1px solid var(--color-border);border-radius:12px;padding:16px}.person{display:flex;justify-content:space-between;padding:10px 0;border-bottom:1px solid var(--color-border)}.person>div:first-child{display:flex;flex-direction:column}.person span,.preview p{font-size:12px;color:var(--color-secondary)}.person button,.preview button{border:0;background:transparent;color:var(--color-primary);cursor:pointer}.preview-kb{display:flex;justify-content:space-between;padding:8px 0}.preview-kb strong{color:var(--color-primary);font-size:12px}.preview label{display:flex;flex-direction:column;gap:5px;margin:10px 0;font-size:13px}.preview input,.preview select{padding:8px;border:1px solid var(--color-border);border-radius:6px}@media(max-width:1000px){.org-layout{grid-template-columns:200px 1fr}.preview{grid-column:1/-1}}</style>
